parameters.jsCode:
// Read persistent storage for current_processing_row.
const staticData = $getWorkflowStaticData('global');
let currentRow = Number(staticData.current_processing_row || 2);
if (!currentRow || currentRow < 2) currentRow = 2;
staticData.current_processing_row = currentRow;

const promptsLoaded = staticData.promptsLoaded || false;

return [{
  json: {
    current_processing_row: currentRow,
    promptsLoaded,
    isFirstCycle: !promptsLoaded
  }
}];

// Save current row and current keyword/product data to persistent workflow storage.
const staticData = $getWorkflowStaticData('global');
const item = $input.first().json;
const row = Number(item.current_processing_row || staticData.current_processing_row || 2);

staticData.current_processing_row = row;
staticData.title_keyword = item.title_keyword || '';
staticData.high_end_products = item.high_end_products || '';
staticData.mid_and_afford_products = item.mid_and_afford_products || '';

const promptsLoaded = staticData.promptsLoaded || false;

return [{
  json: {
    ...item,
    current_processing_row: row,
    isFirstCycle: !promptsLoaded,
    promptsLoaded
  }
}];

// Map original prompt workbook rows by SERIAL NO, not fragile row order.
// Current workbook headers:
//   SERIAL NO = prompt serial, for example 1, 1_1, 4_1
//   PROMT     = original prompt text
const items = $input.all();

const promptIds = [
  'prompt_1', 'prompt_1_1', 'prompt_2', 'prompt_2_1',
  'prompt_4', 'prompt_4_1', 'prompt_4_2', 'prompt_4_3',
  'prompt_5', 'prompt_5_1', 'prompt_5_2', 'prompt_5_3',
  'prompt_5_4', 'prompt_5_5', 'prompt_5_6', 'prompt_5_7',
  'prompt_6', 'prompt_6_1', 'prompt_7', 'prompt_7_1',
  'prompt_8', 'prompt_9', 'prompt_9_1', 'prompt_10',
  'prompt_11', 'prompt_11_1'
];

const normalizeSerial = (value) => {
  const raw = String(value ?? '').trim();
  if (!raw) return '';
  return 'prompt_' + raw.replace(/\./g, '_');
};

const readPromptText = (row) => {
  const value =
    row['PROMT'] ??       // actual current workbook header
    row['PROMTS'] ??
    row['PROMPT'] ??
    row['Promt'] ??
    row['Promts'] ??
    row['Prompt'] ??
    row.B ??
    row[1] ??
    '';
  return String(value ?? '').trim();
};

const result = {};
for (const id of promptIds) result[id] = '';

for (const item of items) {
  const row = item.json || {};
  const serial =
    row['SERIAL NO'] ??
    row['SR.NO'] ??
    row['Serial No'] ??
    row['serial no'] ??
    row.A ??
    row[0] ??
    '';
  const id = normalizeSerial(serial);
  const text = readPromptText(row);
  if (id && Object.prototype.hasOwnProperty.call(result, id) && text) {
    result[id] = text;
  }
}

const missing = promptIds.filter((id) => !String(result[id] || '').trim());
if (missing.length) {
  throw new Error('Missing original prompt text for: ' + missing.join(', '));
}

return [{ json: result }];

const staticData = $getWorkflowStaticData('global');
const row = $input.first().json || {};   // only 1 row, contains all prompts

const promptIds = [
  'prompt_1', 'prompt_1_1', 'prompt_2', 'prompt_2_1',
  'prompt_4', 'prompt_4_1', 'prompt_4_2', 'prompt_4_3',
  'prompt_5', 'prompt_5_1', 'prompt_5_2', 'prompt_5_3',
  'prompt_5_4', 'prompt_5_5', 'prompt_5_6', 'prompt_5_7',
  'prompt_6', 'prompt_6_1', 'prompt_7', 'prompt_7_1',
  'prompt_8', 'prompt_9', 'prompt_9_1', 'prompt_10',
  'prompt_11', 'prompt_11_1'
];

// Store directly by column names
for (const id of promptIds) {
  staticData[id] = (row[id] ?? '').toString();
}

staticData.promptsLoaded = true;

return [{
  json: {
    promptsLoaded: true,
    stored: promptIds.length,
    preview_prompt_1: String(staticData.prompt_1).slice(0, 60),
    preview_prompt_1_1: String(staticData.prompt_1_1).slice(0, 60)
  }
}];

// Load inputs for Section 3: Intro Section Generation
const staticData = $getWorkflowStaticData('global');

return [{ json: {
  prompt_1: staticData.prompt_1 || '',
  prompt_1_1: staticData.prompt_1_1 || '',
  title_keyword: staticData.title_keyword || $input.first().json.title_keyword || '',
  high_end_products: staticData.high_end_products || $input.first().json.high_end_products || ''
} }];

// Build payload for prompt_1
const staticData = $getWorkflowStaticData('global');
const item = $input.first().json || {};

const PROMPT_KEY   = "prompt_1";
const CONTEXT_KEYS = ["title_keyword", "high_end_products"];
const OUTPUT_KEYS  = [];
const STAGE_ID     = "prompt_1";
const USE_SEARCH   = false;
const MAX_TURNS    = 12;

const read = (key) => {
  const v = item[key] ?? staticData[key] ?? '';
  return (v === undefined || v === null) ? '' : String(v);
};

const systemContent = read(PROMPT_KEY);
if (!systemContent.trim()) {
  throw new Error(STAGE_ID + ': prompt "' + PROMPT_KEY + '" is empty. Run the first '
    + 'cycle so the prompt sheet loads into workflow static data.');
}

// Upstream outputs are required input. Empty means the previous stage did not
// store its result, which is the bug that made every rewrite stage run blind.
const parts = [];
for (const key of CONTEXT_KEYS) {
  const v = read(key);
  if (v.trim() !== '') parts.push(key + ':\n' + v);
}
for (const key of OUTPUT_KEYS) {
  const v = read(key);
  if (!v.trim()) {
    throw new Error(STAGE_ID + ': required upstream output "' + key + '" is empty.');
  }
  parts.push(key + ':\n' + v);
}

return [{ json: {
  ...item,
  systemContent,
  userContent: parts.join('\n\n'),
  stageId: STAGE_ID,
  rowNumber: Number(staticData.current_processing_row || 2),
  useWebSearch: USE_SEARCH,
  maxTurns: MAX_TURNS
} }];

